import math

def bt_probability(r_a, r_b):
    d = r_a - r_b
    if d >= 0:
        return 1.0 / (1.0 + math.exp(-d))
    e = math.exp(d)
    return e / (1.0 + e)

def bt_loglik(r_a, r_b, a_won):
    p = bt_probability(r_a, r_b)
    p = min(max(p, 1e-12), 1 - 1e-12)
    return math.log(p) if a_won else math.log(1 - p)
